module TopModule(
    input clk,
    input areset,
    input in,
    output out
);

// Define the states of the Moore state machine
typedef enum logic [1:0] {
    A, B, C, D
} state_t;

// Define the next state logic
state_t next_state;

// Define the output logic
logic out_reg;

// Define the state register
state_t state;

// Define the asynchronous reset logic
always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state <= A;
    end else begin
        state <= next_state;
    end
end

// Define the next state logic
always_comb begin
    case (state)
        A: begin
            if (in == 0) begin
                next_state = B;
            end else begin
                next_state = C;
            end
        end
        B: begin
            if (in == 0) begin
                next_state = C;
            end else begin
                next_state = D;
            end
        end
        C: begin
            if (in == 0) begin
                next_state = A;
            end else begin
                next_state = D;
            end
        end
        D: begin
            if (in == 0) begin
                next_state = C;
            end else begin
                next_state = B;
            end
        end
